function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 500000) return 'nums needs 2 to 5 * 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of nums is a whole number from 1 to 100.';
  const largest = Math.max(...nums);
  const others = nums.filter(v => v !== largest);
  if (nums.length - others.length !== 1) return 'Exactly one value must be the largest.';
  if (others.some(v => v !== others[0])) return 'Every value except the large one must be the same.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [nums] = input;
  const n = nums.length;
  const limit = 20;
  let calls = 0;
  // Prefix sums answer each range sum in O(1), as LeetCode's reader does.
  const prefix = [0];
  for (const value of nums) prefix.push(prefix[prefix.length - 1] + value);
  const sum = (from, to) => prefix[to + 1] - prefix[from];
  const valid = (from, to) => Number.isInteger(from) && Number.isInteger(to) && from >= 0 && from <= to && to < n;
  const reader = {
    length() {
      return n;
    },
    compareSub(l, r, x, y) {
      if (!valid(l, r) || !valid(x, y)) throw new Error(`compareSub(${l}, ${r}, ${x}, ${y}) needs whole-number ranges with 0 <= l <= r < ${n} and 0 <= x <= y < ${n}.`);
      calls++;
      if (calls > limit) throw new Error('compareSub was called more than 20 times; halve the candidate range with each comparison.');
      const first = sum(l, r);
      const second = sum(x, y);
      return first > second ? 1 : first < second ? -1 : 0;
    },
  };
  const result = solve(reader);
  if (!Number.isInteger(result)) throw new Error('Return the index of the large value.');
  return result;
}

