function getIndex(reader) {
  let left = 0;
  let right = reader.length() - 1;

  while (left < right) {
    const half = Math.floor((right - left + 1) / 2);
    const leftEnd = left + half - 1;
    const rightEnd = leftEnd + half;
    const result = reader.compareSub(left, leftEnd, leftEnd + 1, rightEnd);
    if (result === 1) {
      right = leftEnd;
    } else if (result === -1) {
      left = leftEnd + 1;
      right = rightEnd;
    } else {
      return right;
    }
  }
  return left;
}

