function getIndex(reader) {
  // Split the candidates into three parts instead of two: weigh the first third against the second,
  // and if they balance the large value is in the remainder.
  let low = 0;
  let high = reader.length() - 1;
  while (low < high) {
    const third = Math.max(1, Math.floor((high - low + 1) / 3));
    const verdict = reader.compareSub(low, low + third - 1, low + third, low + 2 * third - 1);
    if (verdict > 0) {
      high = low + third - 1;
    } else if (verdict < 0) {
      const start = low + third;
      low = start;
      high = start + third - 1;
    } else {
      low = low + 2 * third;
    }
  }
  return low;
}

