function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 2 + pick(11);
  const base = 1 + pick(99);
  const big = base + 1 + pick(100 - base);
  const roll = rand();
  // Usually a random position; sometimes the first or the last index.
  const at = roll < 0.15 ? 0 : roll < 0.3 ? n - 1 : pick(n);
  return [Array.from({ length: n }, (_, i) => (i === at ? big : base))];
}
